1	/* ============================================================
2	   tierlist.js — 英雄梯度排行榜核心引擎
3	   支持 LOLM（分路/Z-score） 和 曙光英雄（无分路/加权和）
4	   ============================================================ */
5	
6	"use strict";
7	
8	// ---- 全局状态 ----
9	let gameConfig = null;      // 当前游戏的 config.json
10	let gameData = null;        // 计算后的结构化数据
11	let currentMethod = "zscore"; // LOLM: "zscore"|"simple", SG: "weighted"
12	let currentView = "lane";   // "lane"|"global"
13	let currentLane = null;     // 当前分路名（仅 hasLanes）
14	
15	// ---- 工具函数 ----
16	function parsePct(s) {
17	  if (typeof s === "number") return s / 100;
18	  return parseFloat(String(s).replace("%", "")) / 100;
19	}
20	
21	function mean(arr) {
22	  return arr.reduce((a, b) => a + b, 0) / arr.length;
23	}
24	
25	function stdDev(arr) {
26	  const m = mean(arr);
27	  const v = arr.reduce((s, v) => s + (v - m) ** 2, 0) / arr.length;
28	  return Math.sqrt(v) || 1;
29	}
30	
31	function zScores(arr) {
32	  const m = mean(arr);
33	  const s = stdDev(arr);
34	  if (s === 0) return arr.map(() => 0);
35	  return arr.map(v => (v - m) / s);
36	}
37	
38	function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
39	
40	function getRankClass(rank) {
41	  if (rank === 1) return "rank-1";
42	  if (rank === 2) return "rank-2";
43	  if (rank === 3) return "rank-3";
44	  return "";
45	}
46	
47	function getWrClass(val) {
48	  if (val >= 0.52) return "wr-high";
49	  if (val >= 0.49) return "wr-mid";
50	  return "wr-low";
51	}
52	
53	function getCwClass(val) {
54	  // 战力分：高(>140) 中(80-140) 低(<80)
55	  if (val >= 140) return "cw-high";
56	  if (val >= 80) return "cw-mid";
57	  return "cw-low";
58	}
59	
60	// ---- 梯度系统 ----
61	function getTierColors() {
62	  return gameConfig.tiers.colors;
63	}
64	
65	function getTierThresholds() {
66	  return gameConfig.tiers.thresholds;
67	}
68	
69	function getTierBadge(tier) {
70	  const color = getTierColors()[tier] || "#8c8c8c";
71	  return `<span class="tier-badge" style="background:${color}">${tier}</span>`;
72	}
73	
74	function getScoreBar(score, tier) {
75	  const color = getTierColors()[tier] || "#8c8c8c";
76	  return `<div class="score-bar-wrap">
77	    <div class="score-bar"><div class="score-bar-fill" style="width:${score}%;background:${color}"></div></div>
78	    <span class="score-value">${score.toFixed(1)}</span></div>`;
79	}
80	
81	function assignTiers(heroes, scoreKey) {
82	  const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
83	  const n = sorted.length;
84	  const thresholds = getTierThresholds();
85	  sorted.forEach((h, rank) => {
86	    const pct = 1 - rank / n;
87	    let tier = "T4";
88	    for (const t of thresholds) {
89	      if (pct >= t.pct) { tier = t.tier; break; }
90	    }
91	    h.tier = tier;
92	    h.rank = rank + 1;
93	  });
94	}
95	
96	// ============================================================
97	// LOLM 算法
98	// ============================================================
99	function computeLOLM(rawData) {
100	  const hasLanes = gameConfig.hasLanes;
101	  const lanes = {};
102	  const allHeroes = [];
103	
104	  for (const laneCfg of gameConfig.lanes) {
105	    const raw = rawData[laneCfg.name];
106	    if (!raw) continue;
107	    const heroes = raw.map(h => ({
108	      name: h.heroName,
109	      lane: laneCfg.name,
110	      headIcon: gameConfig.headIconPath ? (gameConfig.gameId + "/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
111	      wr: parsePct(h.winRate),
112	      pr: parsePct(h.pickRate),
113	      br: parsePct(h.banRate),
114	      bp: parsePct(h.pickRate) + parsePct(h.banRate)
115	    }));
116	    lanes[laneCfg.name] = heroes;
117	    allHeroes.push(...heroes);
118	  }
119	
120	  // Z-score 加权（分路内计算 Z-score）
121	  for (const [laneName, heroes] of Object.entries(lanes)) {
122	    const zWr = zScores(heroes.map(h => h.wr));
123	    const zPr = zScores(heroes.map(h => h.pr));
124	    const zBr = zScores(heroes.map(h => h.br));
125	    heroes.forEach((h, i) => {
126	      h.z_wr = zWr[i]; h.z_pr = zPr[i]; h.z_br = zBr[i];
127	      h.raw_zscore = 0.5 * zWr[i] + 1.0 * zPr[i] + 3.0 * zBr[i];
128	    });
129	  }
130	
131	  // 简易公式
132	  for (const [laneName, heroes] of Object.entries(lanes)) {
133	    heroes.forEach(h => {
134	      h.raw_simple = Math.pow(h.wr, 0.3) * (h.pr + 2.5 * h.br) * 100;
135	    });
136	  }
137	
138	  // 分路内 min-max 归一化
139	  function normalize(heroes, rawKey, normKey) {
140	    const vals = heroes.map(h => h[rawKey]);
141	    const lo = Math.min(...vals), hi = Math.max(...vals);
142	    const rng = hi - lo || 1;
143	    heroes.forEach(h => { h[normKey] = ((h[rawKey] - lo) / rng) * 100; });
144	  }
145	
146	  for (const [, heroes] of Object.entries(lanes)) {
147	    normalize(heroes, "raw_zscore", "score_zscore");
148	    normalize(heroes, "raw_simple", "score_simple");
149	  }
150	
151	  // 全局归一化
152	  normalize(allHeroes, "raw_zscore", "score_zscore_global");
153	  normalize(allHeroes, "raw_simple", "score_simple_global");
154	
155	  // 分配梯度
156	  for (const [, heroes] of Object.entries(lanes)) {
157	    assignTiersWithKey(heroes, "score_zscore", "tier_zscore");
158	    assignTiersWithKey(heroes, "score_simple", "tier_simple");
159	    assignTiersWithKey(heroes, "score_zscore_global", "tier_global");
160	  }
161	
162	  function assignTiersWithKey(heroes, scoreKey, tierKey) {
163	    const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
164	    const n = sorted.length;
165	    const thresholds = getTierThresholds();
166	    sorted.forEach((h, i) => {
167	      const pct = 1 - i / n;
168	      let tier = "T4";
169	      for (const t of thresholds) {
170	        if (pct >= t.pct) { tier = t.tier; break; }
171	      }
172	      h[tierKey] = tier;
173	      // Store lane rank under a consistent key: _rank_zscore / _rank_simple
174	      if (tierKey === "tier_zscore") h._rank_zscore = i + 1;
175	      if (tierKey === "tier_simple") h._rank_simple = i + 1;
176	    });
177	  }
178	
179	  // 全局排名
180	  const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
181	  globalZ.forEach((h, i) => { h.global_rank_zscore = i + 1; });
182	  const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
183	  globalSimple.forEach((h, i) => { h.global_rank_simple = i + 1; });
184	
185	  return { lanes, allHeroes, globalZ, globalSimple };
186	}
187	
188	// ============================================================
189	// 曙光英雄算法（从 Python validate_pure.py 移植）
190	// ============================================================
191	function computeSG(rawData) {
192	  const heroes = rawData.map(h => ({
193	    name: h.heroName,
194	    appearanceRank: parseInt(h.appearanceRank),
195	    combatPower: parseFloat(h.combatPower),
196	    winRate: parseFloat(String(h.winRate).replace("%", "")) / 100,
197	    lane: null
198	  }));
199	
200	  const N = heroes.length;
201	  const weights = gameConfig.algorithm.weights;
202	
203	  // 出场分：rank 越小越好，转换为 1 → 1.0, N → 0.0
204	  const appearanceScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
205	
206	  // 战力分 min-max 归一化
207	  const combatVals = heroes.map(h => h.combatPower);
208	  const combatMin = Math.min(...combatVals), combatMax = Math.max(...combatVals);
209	  const combatRange = combatMax - combatMin || 1;
210	  const combatScores = combatVals.map(v => (v - combatMin) / combatRange);
211	
212	  // 胜率 min-max 归一化
213	  const wrVals = heroes.map(h => h.winRate);
214	  const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals);
215	  const wrRange = wrMax - wrMin || 1;
216	  const wrScores = wrVals.map(v => (v - wrMin) / wrRange);
217	
218	  // 加权和
219	  heroes.forEach((h, i) => {
220	    h.raw_weighted = weights.appearance * appearanceScores[i]
221	                   + weights.combat * combatScores[i]
222	                   + weights.winrate * wrScores[i];
223	  });
224	
225	  // 最终 min-max 归一化 → 0~100
226	  const rawVals = heroes.map(h => h.raw_weighted);
227	  const rawMin = Math.min(...rawVals), rawMax = Math.max(...rawVals);
228	  const rawRange = rawMax - rawMin || 1;
229	  heroes.forEach(h => { h.score = ((h.raw_weighted - rawMin) / rawRange) * 100; });
230	
231	  // 分配梯度
232	  const sorted = [...heroes].sort((a, b) => b.score - a.score);
233	  const thresholds = getTierThresholds();
234	  sorted.forEach((h, i) => {
235	    const pct = 1 - i / N;
236	    let tier = "T4";
237	    for (const t of thresholds) {
238	      if (pct >= t.pct) { tier = t.tier; break; }
239	    }
240	    h.tier = tier;
241	    h.rank = i + 1;
242	  });
243	
244	  return { heroes, sorted };
245	}
246	
247	// ============================================================
248	// 数据加载 + 计算调度
249	// ============================================================
250	async function loadGameData() {
251	  const base = gameConfig.gameId === "lolm" ? "lolm" : "曙光英雄";
252	
253	  if (gameConfig.hasLanes) {
254	    // LOLM: 加载所有分路 JSON
255	    const results = await Promise.all(
256	      gameConfig.lanes.map(async lane => {
257	        const resp = await fetch(base + "/" + lane.dataFile);
258	        if (!resp.ok) throw new Error(`加载 ${lane.dataFile} 失败: ${resp.status}`);
259	        return [lane.name, await resp.json()];
260	      })
261	    );
262	    const rawData = Object.fromEntries(results);
263	    const data = computeLOLM(rawData);
264	
265	    // 转换为标准格式
266	    gameData = {
267	      hasLanes: true,
268	      lanes: {},
269	      allHeroes: data.allHeroes,
270	      globalZ: data.globalZ,
271	      globalSimple: data.globalSimple
272	    };
273	    for (const [name, heroes] of Object.entries(data.lanes)) {
274	      gameData.lanes[name] = heroes;
275	    }
276	  } else {
277	    // 曙光：加载单个 JSON
278	    const resp = await fetch(base + "/" + gameConfig.dataFile);
279	    if (!resp.ok) throw new Error(`加载数据失败: ${resp.status}`);
280	    const rawData = await resp.json();
281	    const data = computeSG(rawData);
282	    gameData = {
283	      hasLanes: false,
284	      heroes: data.heroes,
285	      sorted: data.sorted
286	    };
287	  }
288	}
289	
290	// ============================================================
291	// 获取当前有效的字段
292	// ============================================================
293	function getScoreField(hero) {
294	  if (gameConfig.hasLanes) {
295	    return currentMethod === "zscore" ? "score_zscore" : "score_simple";
296	  }
297	  return "score";
298	}
299	
300	function getTierField(hero) {
301	  if (gameConfig.hasLanes) {
302	    return currentMethod === "zscore" ? "tier_zscore" : "tier_simple";
303	  }
304	  return "tier";
305	}
306	
307	function getGlobalRank(hero) {
308	  if (gameConfig.hasLanes) {
309	    return hero[currentMethod === "zscore" ? "global_rank_zscore" : "global_rank_simple"];
310	  }
311	  return hero.rank;
312	}
313	
314	// ============================================================
315	// 渲染
316	// ============================================================
317	function formatCellValue(hero, col) {
318	  const val = hero[col.field];
319	  if (val == null) return "-";
320	
321	  switch (col.type) {
322	    case "rank":
323	      return `<span class="rank-num ${getRankClass(val)}">${val}</span>`;
324	    case "tier":
325	      return getTierBadge(val);
326	    case "score":
327	      return getScoreBar(val, hero.tier || hero[getTierField(hero)] || "T4");
328	    case "pct": {
329	      const pctVal = val * 100;
330	      let cls = "";
331	      if (col.colorClass === "wr") cls = getWrClass(val);
332	      if (col.colorClass === "cw") cls = getCwClass(val);
333	      return cls ? `<span class="${cls}">${pctVal.toFixed(2)}%</span>` : `${pctVal.toFixed(2)}%`;
334	    }
335	    case "int":
336	      return val.toString();
337	    default:
338	      return String(val);
339	  }
340	}
341	
342	function getSortValue(hero, col) {
343	  const val = hero[col.field];
344	  if (val == null) return 0;
345	  if (col.type === "tier") {
346	    const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
347	    return order.indexOf(val);
348	  }
349	  if (typeof val === "number") return val;
350	  return String(val);
351	}
352	
353	function renderTable(heroes, columns, highlightLane) {
354	  // highlightLane: if set, highlight heroes from that lane
355	  let html = '<div class="table-wrapper"><table><thead><tr>';
356	  columns.forEach((col, idx) => {
357	    html += `<th onclick="sortTable(this, ${idx})" data-col-idx="${idx}">
358	      ${col.label} <span class="sort-icon">↕</span></th>`;
359	  });
360	  html += '</tr></thead><tbody>';
361	
362	  heroes.forEach(h => {
363	    let rowClass = "";
364	    if (highlightLane && h.lane === highlightLane) rowClass = ' class="current-highlight"';
365	    html += `<tr${rowClass}>`;
366	    columns.forEach(col => {
367	      // Resolve field value — some are computed
368	      let displayVal;
369	      if (col.field === "score") {
370	        displayVal = h[getScoreField(h)];
371	      } else if (col.field === "scoreGlobal") {
372	        displayVal = h[gameConfig.hasLanes ? (currentMethod === "zscore" ? "score_zscore_global" : "score_simple_global") : "score"];
373	      } else if (col.field === "tier") {
374	        displayVal = gameConfig.hasLanes ? h[getTierField(h)] : h.tier;
375	      } else if (col.field === "globalRank") {
376	        displayVal = getGlobalRank(h);
377	      } else {
378	        displayVal = h[col.field];
379	      }
380	
381	      // Format
382	      if (col.type === "rank") {
383	        html += `<td class="rank-num ${getRankClass(displayVal)}">${displayVal}</td>`;
384	      } else if (col.type === "tier") {
385	        html += `<td>${getTierBadge(displayVal)}</td>`;
386	      } else if (col.type === "score") {
387	        html += `<td>${getScoreBar(displayVal, h.tier || displayVal)}</td>`;
388	      } else if (col.type === "pct" && displayVal != null) {
389	        const pctVal = displayVal * 100;
390	        let cls = "";
391	        if (col.colorClass === "wr") cls = getWrClass(displayVal);
392	        if (col.colorClass === "cw") cls = getCwClass(displayVal);
393	        html += `<td class="${cls}">${pctVal.toFixed(2)}%</td>`;
394	      } else if (col.type === "int" && displayVal != null) {
395	        let cls = "";
396	        if (col.colorClass === "cw") cls = getCwClass(displayVal);
397	        html += `<td class="${cls}">${displayVal}</td>`;
398	      } else {
399	        let txt = displayVal != null ? displayVal : "-";
400	        // Render head icon + name for text columns when hero has an icon
401	        if (col.type === "text" && col.field === "name" && h.headIcon) {
402	          txt = `<div class="hero-cell"><img class="hero-icon" src="${h.headIcon}" alt="${h.name}" onerror="this.style.display='none'"> <span class="hero-name">${txt}</span></div>`;
403	        } else if (col.type === "text" && col.field === "name") {
404	          txt = `<span class="hero-name">${txt}</span>`;
405	        }
406	        html += `<td>${txt}</td>`;
407	      }
408	    });
409	    html += '</tr>';
410	  });
411	
412	  html += '</tbody></table></div>';
413	  return html;
414	}
415	
416	function renderStatCards(heroes) {
417	  const cards = gameConfig.statCards;
418	  let html = '<div class="stats-row">';
419	  cards.forEach(card => {
420	    let displayVal;
421	    if (card.field === "winRateRange") {
422	      const wrVals = heroes.map(h => h.winRate * 100);
423	      displayVal = `${Math.min(...wrVals).toFixed(1)}% ~ ${Math.max(...wrVals).toFixed(1)}%`;
424	    } else if (card.field === "count") {
425	      displayVal = heroes.length;
426	    } else if (card.format === "pct") {
427	      const vals = heroes.map(h => h[card.field] * 100);
428	      displayVal = mean(vals).toFixed(1) + "%";
429	    } else if (card.format === "int") {
430	      const vals = heroes.map(h => h[card.field]);
431	      displayVal = Math.round(mean(vals));
432	    } else {
433	      displayVal = String(heroes.length);
434	    }
435	    html += `<div class="stat-card">
436	      <div class="stat-value">${displayVal}</div>
437	      <div class="stat-label">${card.label}</div></div>`;
438	  });
439	  html += '</div>';
440	  return html;
441	}
442	
443	function renderLaneView(laneName) {
444	  if (!gameData.hasLanes) {
445	    // 曙光：无分路，直接全量渲染
446	    const heroes = gameData.heroes;
447	    const sorted = [...heroes].sort((a, b) => a.rank - b.rank);
448	    let html = `<div class="section-header">
449	      <h2>${gameConfig.gameIcon} ${gameConfig.gameName} 梯度排行</h2>
450	      <span class="count-badge">${heroes.length} 个英雄</span></div>`;
451	    html += renderStatCards(heroes);
452	    html += renderTable(sorted, gameConfig.columns, null);
453	    return html;
454	  }
455	
456	  // LOLM：分路渲染
457	  const heroes = gameData.lanes[laneName];
458	  if (!heroes) return "<p>无数据</p>";
459	
460	  const scoreKey = getScoreField();
461	  const tierKey = getTierField();
462	  const rankKey = currentMethod === "zscore" ? "_rank_zscore" : "_rank_simple";
463	  const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
464	  // Set display rank from precomputed lane rank
465	  sorted.forEach((h) => { h.laneRank = h[rankKey]; });
466	
467	  // Build lane-specific columns (with global rank column appended)
468	  const laneCols = gameConfig.columns.map(col => {
469	    if (col.field === "rank") return { ...col, field: "laneRank" };
470	    return col;
471	  });
472	  // Append global rank column
473	  laneCols.push({ label: "全局排名", field: "globalRank", type: "rank" });
474	
475	  let html = `<div class="section-header">
476	    <h2>${laneName}</h2>
477	    <span class="count-badge">${heroes.length} 个英雄</span></div>`;
478	  html += renderStatCards(heroes);
479	  html += renderTable(sorted, laneCols, null);
480	  return html;
481	}
482	
483	function renderGlobalView() {
484	  if (!gameData.hasLanes) {
485	    // 曙光无分路模式没有"全局"视图，显示一个汇总
486	    return renderLaneView();
487	  }
488	
489	  const all = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
490	  // Re-rank
491	  all.forEach((h, i) => { h.globalRank = i + 1; });
492	
493	  let html = `<div class="section-header">
494	    <h2>🌍 全局排名（跨分路对比）</h2>
495	    <span class="count-badge">${all.length} 个英雄</span>
496	    <span class="hint">⚠️ 不同分路英雄职责不同，建议以分路内排名为主</span></div>`;
497	  html += renderTable(all, gameConfig.globalColumns, null);
498	  return html;
499	}
500	
501	function renderAll() {
502	  if (!gameData) return;
503	  const content = document.getElementById("content");
504	
505	  if (!gameData.hasLanes) {
506	    content.innerHTML = renderLaneView();
507	    return;
508	  }
509	
510	  if (currentView === "global") {
511	    content.innerHTML = renderGlobalView();
512	  } else {
513	    content.innerHTML = renderLaneView(currentLane);
514	  }
515	}
516	
517	// ============================================================
518	// 搜索
519	// ============================================================
520	function doSearch(query) {
521	  if (!query || query.trim().length === 0) {
522	    renderAll();
523	    return;
524	  }
525	  const q = query.trim().toLowerCase();
526	  let results = [];
527	
528	  if (gameData.hasLanes) {
529	    for (const heroes of Object.values(gameData.lanes)) {
530	      for (const h of heroes) {
531	        if (h.name.toLowerCase().includes(q)) results.push(h);
532	      }
533	    }
534	  } else {
535	    results = gameData.heroes.filter(h => h.name.toLowerCase().includes(q));
536	  }
537	
538	  if (results.length === 0) {
539	    document.getElementById("content").innerHTML =
540	      `<p style="text-align:center;padding:40px;color:#8b949e;">未找到匹配 "${query}" 的英雄</p>`;
541	    return;
542	  }
543	
544	  // Sort by score descending
545	  const scoreKey = getScoreField();
546	  const rankKey = gameData.hasLanes ? (currentMethod === "zscore" ? "_rank_zscore" : "_rank_simple") : "rank";
547	  results.sort((a, b) => b[scoreKey] - a[scoreKey]);
548	  // Set laneRank for display
549	  results.forEach(h => { h.laneRank = h[rankKey] || 0; });
550	
551	  // Search result columns
552	  let searchCols;
553	  if (gameData.hasLanes) {
554	    searchCols = [
555	      { label: "分路排名", field: "laneRank", type: "rank" },
556	      { label: "英雄", field: "name", type: "text" },
557	      { label: "分路", field: "lane", type: "text" },
558	      { label: "梯度", field: "tier", type: "tier" },
559	      { label: "评分", field: "score", type: "score" },
560	      { label: "胜率", field: "wr", type: "pct", colorClass: "wr" },
561	      { label: "出场率", field: "pr", type: "pct" },
562	      { label: "Ban率", field: "br", type: "pct" },
563	      { label: "BP率", field: "bp", type: "pct" },
564	      { label: "全局排名", field: "globalRank", type: "rank" }
565	    ];
566	  } else {
567	    searchCols = gameConfig.columns;
568	  }
569	
570	  let html = `<div class="section-header">
571	    <h2>🔍 搜索结果："${query}"</h2>
572	    <span class="count-badge">${results.length} 个英雄</span></div>`;
573	  html += renderTable(results, searchCols, null);
574	  document.getElementById("content").innerHTML = html;
575	}
576	
577	// ============================================================
578	// 表格排序
579	// ============================================================
580	function sortTable(th, colIdx) {
581	  const table = th.closest("table");
582	  const tbody = table.querySelector("tbody");
583	  const rows = Array.from(tbody.querySelectorAll("tr"));
584	  const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");
585	
586	  table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
587	  th.classList.add("sorted");
588	  if (isDesc) th.classList.add("desc");
589	
590	  // Determine which heroes list is active
591	  let heroes;
592	  if (gameData.hasLanes) {
593	    if (currentView === "global") {
594	      heroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
595	    } else {
596	      heroes = gameData.lanes[currentLane] || [];
597	    }
598	  } else {
599	    heroes = gameData.heroes;
600	  }
601	
602	  // Build column definitions
603	  let cols;
604	  if (gameData.hasLanes && currentView === "global") {
605	    cols = gameConfig.globalColumns;
606	  } else {
607	    cols = gameConfig.columns;
608	  }
609	
610	  // Handle lane-specific rank column
611	  const col = (colIdx < cols.length) ? cols[colIdx] : { field: "globalRank", type: "rank" };
612	
613	  rows.sort((a, b) => {
614	    const heroA = heroes.find(h => h.name === a.cells[1]?.textContent?.trim());
615	    const heroB = heroes.find(h => h.name === b.cells[1]?.textContent?.trim());
616	    const va = heroA ? (col.field === "laneRank" ? heroA.laneRank : heroA[col.field]) : 0;
617	    const vb = heroB ? (col.field === "laneRank" ? heroB.laneRank : heroB[col.field]) : 0;
618	
619	    if (col.type === "tier") {
620	      const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
621	      const ia = order.indexOf(va), ib = order.indexOf(vb);
622	      return isDesc ? ib - ia : ia - ib;
623	    }
624	    const na = parseFloat(va), nb = parseFloat(vb);
625	    if (!isNaN(na) && !isNaN(nb)) {
626	      return isDesc ? nb - na : na - nb;
627	    }
628	    const sa = String(va != null ? va : ""), sb = String(vb != null ? vb : "");
629	    return isDesc ? sb.localeCompare(sa) : sa.localeCompare(sb);
630	  });
631	
632	  rows.forEach(r => tbody.appendChild(r));
633	}
634	
635	// ============================================================
636	// 导航与控制
637	// ============================================================
638	function switchMethod(method) {
639	  currentMethod = method;
640	  // Update buttons
641	  document.querySelectorAll(".controls button").forEach(b => {
642	    const txt = b.textContent;
643	    if (txt.includes("Z-score") || txt.includes("简易公式") || txt.includes("加权和")) {
644	      const isZ = txt.includes("Z-score");
645	      const isS = txt.includes("简易公式");
646	      const isW = txt.includes("加权和");
647	      b.className = (isZ && method === "zscore") || (isS && method === "simple") || (isW && method === "weighted") ? "active" : "";
648	    }
649	  });
650	  renderAll();
651	}
652	
653	function switchView(view) {
654	  currentView = view;
655	  document.getElementById("btn-lane").className = view === "lane" ? "active" : "";
656	  const btnGlobal = document.getElementById("btn-global");
657	  if (btnGlobal) btnGlobal.className = view === "global" ? "active" : "";
658	
659	  if (view === "lane" && gameData.hasLanes) {
660	    currentLane = currentLane || Object.keys(gameData.lanes)[0];
661	    document.querySelectorAll("#nav button").forEach(b => {
662	      b.className = b.textContent === currentLane ? "active" : "";
663	    });
664	  } else if (gameData.hasLanes) {
665	    document.querySelectorAll("#nav button").forEach(b => b.className = "");
666	  }
667	  renderAll();
668	}
669	
670	function buildControls() {
671	  const controls = document.getElementById("controls");
672	  if (!controls) return;
673	
674	  let html = "";
675	  if (gameConfig.hasLanes && gameConfig.algorithm.type === "zscore") {
676	    html += `<span class="label">算法：</span>
677	      <button class="active" onclick="switchMethod('zscore')">Z-score 加权</button>
678	      <button onclick="switchMethod('simple')">简易公式</button>`;
679	  } else if (!gameConfig.hasLanes) {
680	    html += `<span class="label">算法：</span>
681	      <button class="active" onclick="switchMethod('weighted')">加权和 (0.20/0.50/0.30)</button>`;
682	  }
683	
684	  if (gameConfig.hasLanes) {
685	    html += `<span style="margin-left:16px" class="label">视图：</span>
686	      <button id="btn-lane" class="active" onclick="switchView('lane')">📋 分路排名</button>
687	      <button id="btn-global" onclick="switchView('global')">🌍 全局排名</button>`;
688	  }
689	
690	  html += `<input type="text" class="search-box" placeholder="🔍 搜索英雄..." oninput="doSearch(this.value)" style="margin-left:16px">`;
691	  controls.innerHTML = html;
692	}
693	
694	function buildNav() {
695	  const nav = document.getElementById("nav");
696	  if (!nav) return;
697	
698	  if (!gameData.hasLanes) {
699	    nav.style.display = "none";
700	    return;
701	  }
702	
703	  nav.style.display = "flex";
704	  nav.innerHTML = "";
705	  if (!gameData.lanes) return;
706	  Object.keys(gameData.lanes).forEach(lane => {
707	    const btn = document.createElement("button");
708	    btn.textContent = lane;
709	    btn.className = lane === currentLane ? "active" : "";
710	    btn.onclick = () => {
711	      currentLane = lane;
712	      switchView("lane");
713	    };
714	    nav.appendChild(btn);
715	  });
716	}
717	
718	// ============================================================
719	// 游戏切换
720	// ============================================================
721	async function switchGame(gameId) {
722	  // Update game selector buttons
723	  document.querySelectorAll(".game-selector button").forEach(b => {
724	    b.className = b.dataset.game === gameId ? "active" : "";
725	  });
726	
727	  // Load config
728	  const base = gameId === "lolm" ? "lolm" : "曙光英雄";
729	  const configResp = await fetch(base + "/config.json");
730	  if (!configResp.ok) throw new Error(`加载 ${gameId} 配置失败: ${configResp.status}`);
731	  gameConfig = await configResp.json();
732	
733	  // Reset state
734	  currentMethod = gameConfig.algorithm.type === "weighted" ? "weighted" : "zscore";
735	  currentView = "lane";
736	  currentLane = gameConfig.hasLanes ? gameConfig.lanes[0].name : null;
737	
738	  // Clear search box
739	  const searchBox = document.querySelector(".search-box");
740	  if (searchBox) searchBox.value = "";
741	
742	  // Load data
743	  document.getElementById("content").innerHTML =
744	    '<p style="text-align:center;padding:60px;color:#8b949e;">⏳ 加载中...</p>';
745	
746	  await loadGameData();
747	
748	  // Rebuild UI
749	  buildControls();
750	  buildNav();
751	  updateHeader();
752	  renderAll();
753	  updateFooter();
754	}
755	
756	function updateHeader() {
757	  const h1 = document.querySelector(".header h1");
758	  if (h1) h1.innerHTML = `${gameConfig.gameIcon} ${gameConfig.gameName} 英雄梯度排行榜`;
759	}
760	
761	function updateFooter() {
762	  const footer = document.querySelector(".footer");
763	  if (footer) footer.textContent = gameConfig.footer;
764	}
765	
766	// ============================================================
767	// URL 状态
768	// ============================================================
769	function syncURL() {
770	  const params = new URLSearchParams();
771	  if (gameConfig) params.set("game", gameConfig.gameId);
772	  if (currentMethod) params.set("method", currentMethod);
773	  if (currentView) params.set("view", currentView);
774	  if (currentLane) params.set("lane", currentLane);
775	  const newUrl = window.location.pathname + "?" + params.toString();
776	  if (window.location.search !== "?" + params.toString()) {
777	    window.history.replaceState(null, "", newUrl);
778	  }
779	}
780	
781	// ============================================================
782	// 启动
783	// ============================================================
784	async function init() {
785	  // Parse URL params
786	  const params = new URLSearchParams(window.location.search);
787	  const gameId = params.get("game") || "lolm";
788	
789	  await switchGame(gameId);
790	}
791	
792	// Auto-start
793	document.addEventListener("DOMContentLoaded", init);
