  const na = parseFloat(va), nb = parseFloat(vb);
  if (!isNaN(na) && !isNaN(nb)) {
    return isDesc ? nb - na : na - nb;
  }
  const sa = String(va != null ? va : ""), sb = String(vb != null ? vb : "");
  return isDesc ? sb.localeCompare(sa) : sa.localeCompare(sb);
});

