function renderGridView(heroes, highlightLane) {
  // 按梯度分组
  const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
  const colors = getTierColors();
  const groups = {};
  tierOrder.forEach(t => { groups[t] = []; });

  heroes.forEach(h => {
    const tier = gameConfig.hasLanes ? h[getTierField(h)] : h.tier;
    if (groups[tier]) groups[tier].push(h);
    else groups["T4"] = groups["T4"] || []; groups["T4"].push(h);
  });

  // 组内按分数排序
  const scoreKey = getScoreField();
  tierOrder.forEach(t => {
    if (groups[t]) groups[t].sort((a, b) => b[scoreKey] - a[scoreKey]);
  });

  let html = '<div class="tier-grid">';
  tierOrder.forEach(t => {
    const list = groups[t] || [];
    const color = colors[t] || "#8c8c8c";
    html += `<div class="tier-row${list.length === 0 ? " tier-row-empty" : ""}">`;
    html += `<div class="tier-label" style="background:${color}">${t}</div>`;
    html += '<div class="tier-icons">';
    if (list.length === 0) {
      html += '暂无英雄';
    } else {
      list.forEach(h => {
        const name = h.name;
        html += `<div class="tier-hero" title="${name}" onclick="doSearch('${name.replace(/'/g, "\\'")}')">`;
        if (h.headIcon) {
          html += `<img src="${h.headIcon}" alt="${name}" loading="lazy" onerror="this.style.display='none'">`;
        } else {
          html += `<div class="hero-icon-placeholder" style="width:44px;height:44px;border-radius:50%;background:#21262d;border:2px solid #30363d"></div>`;
        }
        html += `<span class="tier-hero-name">${name}</span>`;
        html += '</div>';
      });
    }
    html += '</div></div>';
  });
  html += '</div>';
  return html;
}

