function renderAll() {
  if (!gameData) return;
  const content = document.getElementById("content");

  // 网格视图 — 单独处理
  if (currentViewMode === "grid") {
    let heroes;
    if (!gameData.hasLanes) {
      heroes = gameData.heroes;
